using AlshrouqSchool.Application.Features.Gallery.Commands.Media; using AlshrouqSchool.Application.Features.Gallery.Commands.PostMedia; using AlshrouqSchool.Application.Features.Gallery.Commands.Posts; using FluentValidation;
namespace AlshrouqSchool.Application.Features.Gallery.Validators;
public sealed class CreatePostCommandValidator:AbstractValidator<CreatePostCommand>{public CreatePostCommandValidator(){RuleFor(x=>x.Dto.Title).NotEmpty().MaximumLength(250);RuleFor(x=>x.Dto.Slug).NotEmpty().MaximumLength(300).Matches("^[a-z0-9-]+$");RuleFor(x=>x.Dto.Content).NotEmpty();RuleFor(x=>x.Dto.DisplayOrder).GreaterThanOrEqualTo(0);}}
public sealed class UpdatePostCommandValidator:AbstractValidator<UpdatePostCommand>{public UpdatePostCommandValidator(){RuleFor(x=>x.Id).GreaterThan(0);RuleFor(x=>x.Dto.Title).NotEmpty().MaximumLength(250);RuleFor(x=>x.Dto.Slug).NotEmpty().MaximumLength(300).Matches("^[a-z0-9-]+$");RuleFor(x=>x.Dto.Content).NotEmpty();RuleFor(x=>x.Dto.DisplayOrder).GreaterThanOrEqualTo(0);}}
public sealed class CreateMediaCommandValidator:AbstractValidator<CreateMediaCommand>{public CreateMediaCommandValidator(){RuleFor(x=>x.Dto.FileName).NotEmpty().MaximumLength(255);RuleFor(x=>x.Dto.FilePath).NotEmpty().MaximumLength(500);RuleFor(x=>x.Dto.MimeType).NotEmpty().MaximumLength(50);RuleFor(x=>x.Dto.FileSizeBytes).GreaterThan(0);RuleFor(x=>x.Dto.UploadedByUserId).NotEmpty();}}
public sealed class UpdateMediaCommandValidator:AbstractValidator<UpdateMediaCommand>{public UpdateMediaCommandValidator(){RuleFor(x=>x.Id).GreaterThan(0);RuleFor(x=>x.Dto.FileName).NotEmpty().MaximumLength(255);RuleFor(x=>x.Dto.FilePath).NotEmpty().MaximumLength(500);RuleFor(x=>x.Dto.MimeType).NotEmpty().MaximumLength(50);RuleFor(x=>x.Dto.FileSizeBytes).GreaterThan(0);}}
public sealed class AttachMediaToPostCommandValidator:AbstractValidator<AttachMediaToPostCommand>{public AttachMediaToPostCommandValidator(){RuleFor(x=>x.Dto.PostId).GreaterThan(0);RuleFor(x=>x.Dto.MediaId).GreaterThan(0);RuleFor(x=>x.Dto.DisplayOrder).GreaterThanOrEqualTo(0);}}
public sealed class ReorderPostMediaCommandValidator:AbstractValidator<ReorderPostMediaCommand>{public ReorderPostMediaCommandValidator(){RuleFor(x=>x.Dto.PostId).GreaterThan(0);RuleFor(x=>x.Dto.Items).NotEmpty();RuleForEach(x=>x.Dto.Items).ChildRules(i=>{i.RuleFor(x=>x.PostMediaId).GreaterThan(0);i.RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);});}}